import React, { useState, useEffect } from "react";
import Banner from "./Banner";
import "../styles/main.css";

export default function AdminGallery() {
  // Initial gallery images from public/assets
  const initialImages = Array.from({ length: 16 }, (_, i) => `/assets/GalleryImg${i + 1}.jpg`);

  const [images, setImages] = useState(initialImages);
  const [newFiles, setNewFiles] = useState([]);

  // Handle new image uploads (frontend preview)
  const handleUpload = (e) => {
    const files = Array.from(e.target.files);
    const previews = files.map(file => URL.createObjectURL(file));
    setImages(prev => [...prev, ...previews]);
    setNewFiles(prev => [...prev, ...files]); // store files for future processing if needed
  };

  // Delete image
  const handleDelete = (index) => {
    if (window.confirm("Are you sure you want to delete this image?")) {
      setImages(prev => prev.filter((_, i) => i !== index));
      setNewFiles(prev => prev.filter((_, i) => i !== index)); // remove from newFiles too
    }
  };

  return (
    <>
      <Banner />
      <div className="admin-gallery-page">
        <h2>Manage Gallery</h2>

        <div className="upload-section">
          <input
            type="file"
            multiple
            accept="image/*"
            onChange={handleUpload}
          />
        </div>

        {images.length === 0 ? (
          <p>No images in the gallery.</p>
        ) : (
          <div className="gallery-grid">
            {images.map((img, idx) => (
              <div className="gallery-card" key={idx}>
                <img src={img} alt={`Gallery ${idx + 1}`} />
                <button className="delete-btn" onClick={() => handleDelete(idx)}>Delete</button>
              </div>
            ))}
          </div>
        )}
      </div>
    </>
  );
}
